We say that \cref{eq} satisfies 
\textit{Yong's first stability condition} 
if the following requirements hold:
\begin{enumerate}[label={(\roman{enumi})}]
  \item \label{cond:Yong1}
  All the eigenvalues of the matrix $B$ in \cref{eq:Yong1_PQPinv} 
  have negative real parts;
  \item \label{cond:Yong2}
  \Cref{eq} is \textit{symmetrizable hyperbolic}, i.e., there 
  exists a positive definite Hermitian matrix $A_0$ such that 
  $A_0 A_j = A_j^* A_0$
  for each $j = 1, 2, \ldots, d$;
  \item \label{cond:Yong3w}
  The hyperbolic and source terms satisfies 
  \begin{displaymath}
    A_0 Q + Q^* A_0 \le 0.
  \end{displaymath}
\end{enumerate}
We say that \cref{eq} satisfies 
\textit{Yong's second stability condition} 
if it satisfies the requirements 
\ref{cond:Yong1}, \ref{cond:Yong2}, and 
\begin{enumerate}[start=3,label={(\roman{enumi})$^\prime$}]
  \item \label{cond:Yong3s}
  The hyperbolic and source terms are coupled in the sense that 
  \begin{displaymath}
