Let us begin with basic estimates of the following integral:
\begin{equation}\label{equ:integral}
  \mathcal{I}(\alpha_1, \alpha_2, \beta_1, \beta_2) := 
  \int_{- \infty}^{+ \infty} \frac{1}{|y - \alpha_1| + \beta_1} 
  \cdot \frac{1}{|y - \alpha_2| + \beta_2} \,\mathrm{d} y.
\end{equation}

\begin{equation}\label{equ:integral}
  \mathcal{I}(\alpha_1, \alpha_2, \beta_1, \beta_2) := 
  \int_{- \infty}^{+ \infty} \frac{1}{|y - \alpha_1| + \beta_1} 
  \cdot \frac{1}{|y - \alpha_2| + \beta_2} \,\mathrm{d} y.
\end{equation}

\label{lemma:integral}
  The following estimates of the integral defined in 
  \cref{equ:integral} hold:
  \begin{enumerate}
    \item If $\beta_1 = \beta_2 = \beta$, then 
    \begin{displaymath}
      \mathcal{I}(\alpha_1, \alpha_2, \beta, \beta) = 
      \begin{cases}
        \frac{4 (d + 1) \log(d + 1)}{\beta d (d + 2)} 
        < \frac{2}{\beta}, & \quad \text{ if } d > 0, \\
        \frac{2}{\beta}, & \quad \text{ if } d = 0,
      \end{cases}
    \end{displaymath}
    where $d = \frac{|\alpha_1 - \alpha_2|}{\beta} \ge 0$;
    \item If $\beta_1 \ne \beta_2$, then 
    \begin{displaymath}
      \mathcal{I}(\alpha_1, \alpha_2, \beta_1, \beta_2) \le 
      2 \frac{\log \beta_1 - \log \beta_2}{\beta_1 - \beta_2} <
      \frac{2}{\min \left\{ \beta_1, \beta_2 \right\}}.
    \end{displaymath}
  \end{enumerate}

The first conclusion is straightforward by direct calculation and 
by noticing that the function 
$f(d) := \frac{4 (d + 1) \log (d + 1)}{d (d + 2)}$ is strictly 
decreasing on $(0, + \infty)$, and it has the limit 
$\lim_{d \rightarrow 0} f(d) = 2$.

As for the second conclusion, we notice that 
\begin{displaymath}
  \int_{- \infty}^{+ \infty} 
  \left( \frac{1}{|y - \alpha_1| + \beta_1} 
  - \frac{1}{|y - \alpha_2| + \beta_1} \right) \cdot 
  \left( \frac{1}{|y - \alpha_1| + \beta_2} 
  - \frac{1}{|y - \alpha_2| + \beta_2} \right) \,\mathrm{d} y \ge 0,
\end{displaymath}
and that 
\begin{displaymath}
  \begin{aligned}
    & \int_{- \infty}^{+ \infty} \frac{1}{|y - \alpha_1| + \beta_1} 
    \left( \frac{1}{|y - \alpha_1| + \beta_2} - 
    \frac{1}{|y - \alpha_2| + \beta_2} \right) \,\mathrm{d} y \\
    = & \int_{- \infty}^{+ \infty}
    \frac{1}{|y - \alpha_2| + \beta_1} 
    \left( \frac{1}{|y - \alpha_2| + \beta_2} - 
    \frac{1}{|y - \alpha_1| + \beta_2} \right) \,\mathrm{d} y.
  \end{aligned}
\end{displaymath}
Therefore, 
\begin{displaymath}
  \mathcal{I}(\alpha_1, \alpha_2, \beta_1, \beta_2) \le 
  \mathcal{I}(\alpha_1, \alpha_1, \beta_1, \beta_2) = 
  2 \frac{\log \beta_1 - \log \beta_2}{\beta_1 - \beta_2} <
  \frac{2}{\min \left\{ \beta_1, \beta_2 \right\}},
\end{displaymath}
by direct calculation.

\label{lemma:gRL}
  Assume that the $r \times r$ matrix $B$ is invertible and 
  quasi-stable, the $r \times r$ matrix $M$ is arbitrary,
  and the function $f \in C^1([0, T])$ for a fixed $T > 0$.
  The following estimate holds for 
  $\eta \ge 6 \gamma \delta^{-1}$:
  \begin{displaymath}
    \bigg\| \int_0^T \exp \big( (\eta B + M) (T - s) \big) f(s) 
    \,\mathrm{d} s \bigg\| \le \frac{32 \sqrt{2} r K e^{\gamma T}}
    {\pi \eta \delta} \|f\|_{C^1([0, T])} \log 
    \frac{\eta \delta + \gamma}{\gamma},
  \end{displaymath}
  where $K$ and $\delta$ depend on the matrix $B$, and 
  $\gamma = 2 K \norm{M} + 1$.
  Furthermore, if the matrix $M$ and the function 
  $f \in C^1([0, +\infty))$ take the form of 
  \begin{displaymath}
    M = M(\theta) = \sum_{j = 1}^d \theta_j M_j, \quad 
    f = f(\cdot; \theta),
  \end{displaymath}
  respectively, where $\theta \in \mathbb{R}^d$, the matrices $M_j$ with 
  $j = 1, 2, \ldots, d$ are chosen such that the set of matrices,
  \begin{displaymath}
    \mathcal{F} = \left\{ \eta B + M(\theta) \,\big|\, 
    \theta \in \mathbb{R}^d, \eta \ge 0 \right\},
  \end{displaymath}
  is uniformly quasi-stable, 
  and the function $f(\cdot; \theta)$ satisfies 
  \begin{displaymath}
    f(\cdot; \omega \theta) = f(\omega \cdot; \theta),
  \end{displaymath}
  for each $\omega > 0$,
  then the following estimate holds for $\eta >\beta (|\theta| + 1)$:
  \begin{multline*}
    \bigg\| \int_0^T \exp \big( (\eta B + M(\theta)) (T - s) \big) 
    f(s; \theta) \,\mathrm{d} s \bigg\| \\ \le
    \frac{16 \sqrt{2} r \tilde{K} e^T}{\pi \eta \tilde{\delta}} 
    \sup_{|\theta| = 1} \|f(\cdot; \theta)\|_{C^1([0, T])} 
    \log(\eta \tilde{\delta} + 1), 
  \end{multline*}
  where $\tilde{K} > 0$ and $\beta > 0$ depend on the matrix 
  set $\mathcal{F}$, and $\tilde{\delta} > 0$ depends on the matrix $B$.

\begin{multline*}
    \bigg\| \int_0^T \exp \big( (\eta B + M(\theta)) (T - s) \big) 
    f(s; \theta) \,\mathrm{d} s \bigg\| \\ \le
    \frac{16 \sqrt{2} r \tilde{K} e^T}{\pi \eta \tilde{\delta}} 
    \sup_{|\theta| = 1} \|f(\cdot; \theta)\|_{C^1([0, T])} 
    \log(\eta \tilde{\delta} + 1), 
  \end{multline*}

For a complex number $z \in \mathbb{C}$, let us denote its real part and 
imaginary part by $\gamma = \Re(z)$ and $y = \Im(z)$, respectively, 
i.e., $z = \gamma + i y$ with $\gamma, y \in \mathbb{R}$.
We consider the zero extension of the function $f$, i.e., we define 
the value of $f(t)$ as $f(t) \equiv 0$ for each $t > T$, and we 
still use the notation $f(t)$.
The Laplace transform $\tilde{f}(z)$ of $f(t)$ is given as follows,
\begin{multline*}
  \tilde{f}(z) := \int_0^T e^{- z t} f(t) \,\mathrm{d} t = 
  \int_0^T e^{- i t y} e^{- \gamma t} f(t) \,\mathrm{d} t \\
  = \left( \frac{1}{- i y} e^{-i t y} e^{- \gamma t} f(t) \right)
  \bigg|_{t = 0}^{t = T} - \int_0^T \frac{1}{- i y} e^{- i t y}
  \od{}{t} \left( e^{- \gamma t} f(t) \right) \,\mathrm{d} t,
\end{multline*}
which yields the following estimate of $\tilde{f}(z)$:
\begin{multline*}
  |\tilde{f}(z)| \le \min \left\{ \frac{1}{\gamma}, 
  \frac{2 + \gamma^{-1} + e^{- \gamma T}}{|y|} \right\} 
  \|f\|_{C^1([0,T])} \\ 
  \le \min \left\{ \frac{1}{\gamma}, \frac{4}{|y|} \right\}
  \|f\|_{C^1([0,T])}
  \le \frac{8 \|f\|_{C^1([0,T])}}{|y| + 4 \gamma},
\end{multline*}
where the constant $\gamma > 1$ is to be determined.
The Laplace transform $\tilde{R}(z)$ of the function $R(t)$ defined 
as 
\begin{displaymath}
  R(t) = \int_0^t \exp \big( (\eta B + M)(t - s) \big) f(s) \,\mathrm{d} s,
\end{displaymath}
is given by 
\begin{displaymath}
  \tilde{R}(z) = \int_0^{+\infty} e^{- z t} R(t) \,\mathrm{d} t = 
  (z I - \eta B - M)^{-1} \tilde{f}(z).
\end{displaymath}
By the inverse Laplace transform, one can obtain that 
\begin{multline*}
  R(t) = \frac{1}{2 \pi i} 
  \int_{\gamma - i \infty}^{\gamma + i \infty} e^{t z} 
  \tilde{R}(z) \,\mathrm{d} z 
  = \frac{e^{\gamma t}}{2 \pi} \int_{-\infty}^{+\infty}  
  e^{i t y} (z I - \eta B - M)^{-1} \tilde{f}(z) \,\mathrm{d} y \\
  = \frac{e^{\gamma t}}{2 \pi} \int_{-\infty}^{+\infty} 
  e^{i t y} \big( I - (z I - \eta B)^{-1} M \big)^{-1} 
  (z I - \eta B)^{-1} \tilde{f}(z) \,\mathrm{d} y.
\end{multline*}
Since the matrix $B$ is quasi-stable, the set of matrices $\eta B$ 
with $\eta \ge 0$ is uniformly quasi-stable. By \Cref{thm:IKMT}, 
there exists a constant $K > 0$ such that 
\begin{displaymath}
  \|(z I - \eta B)^{-1}\| \le K \max_{\lambda \in \sigma(B)} 
  |z - \eta \lambda|^{-1} \le \frac{K}{\gamma}.
\end{displaymath}
By taking $\gamma = 2 K \|M\| + 1$, one can obtain that 
\begin{displaymath}
  \|(z I - \eta B)^{-1} M\| \le \frac{K \|M\|}{\gamma} < \frac12,
\end{displaymath}
and thus, 
\begin{displaymath}
  \big\| \big( I - (z I - \eta B)^{-1} M \big)^{-1} \big\| < 2.
\end{displaymath}
Therefore, 
\begin{multline*}
  \|R(T)\| \le \frac{e^{\gamma T}}{2 \pi} \int_{-\infty}^{+\infty}
  \big\| \big( I - (z I - \eta B)^{-1} M \big)^{-1} \big\| \cdot 
  \|(z I - \eta B)^{-1}\| \cdot |\tilde{f}(z)| \,\mathrm{d} y \\ 
  \le \frac{K e^{\gamma T}}{\pi}
  \|f\|_{C^1([0, T])} \int_{-\infty}^{+\infty} 
  \max_{\lambda \in \sigma(B)} |z - \eta \lambda|^{-1}
  \frac{8}{|y| + 4 \gamma} \,\mathrm{d} y \\ 
  \le \frac{8 \sqrt{2} K e^{\gamma T}}{\pi} 
  \|f\|_{C^1([0, T])} 
  \sum_{\lambda \in \sigma(B)} \int_{-\infty}^{+\infty} 
  \frac{1}{|y - \eta \Im(\lambda)| + \gamma - \eta \Re(\lambda)}
  \cdot \frac{1}{|y| + 4 \gamma} \,\mathrm{d} y \\ 
  = \frac{8 \sqrt{2} K e^{\gamma T}}{\pi} 
  \|f\|_{C^1([0, T])} \sum_{\lambda \in \sigma(B)} 
  \mathcal{I}(\eta \Im(\lambda), 0, \gamma - \eta \Re(\lambda), 4 \gamma).
\end{multline*}
Note that the matrix $B$ is invertible and quasi-stable, there 
exists a constant $\delta > 0$ dependent on $B$ such that 
for each eigenvalue $\lambda \in \sigma(B)$ either 
$\Re(\lambda) \le - \delta$ or $|\Im(\lambda)| \ge \delta$ holds.
If $\Re(\lambda) \le - \delta$, then 
\begin{displaymath}
  \mathcal{I}(\eta \Im(\lambda), 0, \gamma - \eta \Re(\lambda), 4 \gamma) 
  \le \mathcal{I}(\eta \Im(\lambda), 0, \gamma + \eta \delta, 4 \gamma)
  \le \frac{2}{\eta \delta - 3 \gamma} \log 
  \frac{\eta \delta + \gamma}{4 \gamma}.
\end{displaymath}
If $|\Im(\lambda)| \ge \delta$, then 
\begin{displaymath}
  \mathcal{I}(\eta \Im(\lambda), 0, \gamma - \eta \Re(\lambda), 4 \gamma) 
  \le \mathcal{I}(\eta \delta, 0, \gamma, \gamma) \le 
  \frac{4 (\eta \delta + \gamma)}
  {\eta \delta (\eta \delta + 2 \gamma)} 
  \log \frac{\eta \delta + \gamma}{\gamma}.
\end{displaymath}
Both cases yield that 
\begin{displaymath}
  \mathcal{I}(\eta \Im(\lambda), 0, \gamma - \eta \Re(\lambda), 4 \gamma) 
  \le \frac{4}{\eta \delta} 
  \log \frac{\eta \delta + \gamma}{\gamma},
\end{displaymath}
as long as $\eta \delta \ge 6 \gamma$, which completes 
the proof of the first conclusion of this lemma.

Let us now prove the second conclusion of this lemma. 
The Laplace transform of $f(t; \theta)$ satisfies the following 
scaling property:
\begin{displaymath}
  \tilde{f}(z; \omega \theta) = \omega^{-1}
  \tilde{f}(\omega^{-1} z; \theta), 
\end{displaymath}
for each $\omega > 0$, which yields the following estimate:
\begin{displaymath}
  |\tilde{f}(z; \theta)| \le \frac{8}{|y| + 4 \gamma} 
  \|f(\cdot; |\theta|^{-1} \theta)\|_{C^1([0, +\infty))}.
\end{displaymath}
By applying \Cref{thm:IKMT} on the uniformly quasi-stable matrix 
set $\mathcal{F}$ and using the previous arguments, one can obtain the 
following estimate: 
\begin{multline*}
  \|R(T; \theta)\| \le \frac{4 \sqrt{2} \tilde{K} 
  e^{\tilde{\gamma} T}}{\pi}
  \sup_{|\theta| = 1} \|f(\cdot; \theta)\|_{C^1([0, +\infty))} \\
  \sum_{\lambda \in \sigma(\eta B + M(\theta))} 
  \mathcal{I}(\Im(\lambda), 0, \tilde{\gamma} - \Re(\lambda), 
  4 \tilde{\gamma}),
\end{multline*}
where $\tilde{\gamma} > 0$ is arbitrary and to be determined, 
and $\tilde{K} > 0$ depends on the matrix set $\mathcal{F}$.
Since the matrix $B$ is invertible, there exist constants 
$\tilde{\alpha} > 0$ and $\tilde{\delta} > 0$ dependent on the 
matrix set $\mathcal{F}$ such that if $|\theta| \le \tilde{\alpha} \eta$, 
then for each eigenvalue $\lambda \in \sigma(\eta B + M(\theta))$ 
either $\Re(\lambda) \le - \eta \tilde{\delta}$ or 
$|\Im(\lambda)| \ge \eta \tilde{\delta}$ holds.
If $\Re(\lambda) \le - \eta \tilde{\delta}$, then 
\begin{displaymath}
  \mathcal{I}(\Im(\lambda), 0, \tilde{\gamma} - \Re(\lambda), 
  4 \tilde{\gamma}) \le 
  \mathcal{I}(\Im(\lambda), 0, \tilde{\gamma} + \eta \tilde{\delta}, 
  4 \tilde{\gamma}) \le 
  \frac{2}{\eta \tilde{\delta} - 3 \tilde{\gamma}} 
  \log 
  \frac{\eta \tilde{\delta} + \tilde{\gamma}}{4 \tilde{\gamma}}.
\end{displaymath}
If $|\Im(\lambda)| \ge \eta \tilde{\delta}$, then 
\begin{displaymath}
  \mathcal{I}(\Im(\lambda), 0, \tilde{\gamma} - \Re(\lambda), 
  4 \tilde{\gamma}) \le 
  \mathcal{I}(\eta \tilde{\delta}, 0, \tilde{\gamma}, \tilde{\gamma}) \le 
  \frac{4 (\eta \tilde{\delta} + \tilde{\gamma})}
  {\eta \tilde{\delta} (\eta \tilde{\delta} + 2 \tilde{\gamma})} 
  \log \frac{\eta \tilde{\delta} + \tilde{\gamma}}{\tilde{\gamma}}.
\end{displaymath}
Both cases yield that 
\begin{displaymath}
  \mathcal{I}(\Im(\lambda), 0, \tilde{\gamma} - \Re(\lambda), 
  \tilde{\alpha}_2) \le \frac{4}{\eta \tilde{\delta}} 
  \log \frac{\eta \tilde{\delta} + \tilde{\gamma}}{\tilde{\gamma}},
\end{displaymath}
as long as 
$\eta \tilde{\delta} \ge 6 \tilde{\gamma}$.
One can choose $\tilde{\gamma} = 1$, and then obtain the desired 
result.

\begin{multline*}
    \tilde{f}(z) := \int_0^T e^{- z t} f(t) \,\mathrm{d} t = 
    \int_0^T e^{- i t y} e^{- \gamma t} f(t) \,\mathrm{d} t \\
    = \left( \frac{1}{- i y} e^{-i t y} e^{- \gamma t} f(t) \right)
    \bigg|_{t = 0}^{t = T} - \int_0^T \frac{1}{- i y} e^{- i t y}
    \od{}{t} \left( e^{- \gamma t} f(t) \right) \,\mathrm{d} t,
  \end{multline*}

\begin{multline*}
    |\tilde{f}(z)| \le \min \left\{ \frac{1}{\gamma}, 
    \frac{2 + \gamma^{-1} + e^{- \gamma T}}{|y|} \right\} 
    \|f\|_{C^1([0,T])} \\ 
    \le \min \left\{ \frac{1}{\gamma}, \frac{4}{|y|} \right\}
    \|f\|_{C^1([0,T])}
    \le \frac{8 \|f\|_{C^1([0,T])}}{|y| + 4 \gamma},
  \end{multline*}

\begin{multline*}
    R(t) = \frac{1}{2 \pi i} 
    \int_{\gamma - i \infty}^{\gamma + i \infty} e^{t z} 
    \tilde{R}(z) \,\mathrm{d} z 
    = \frac{e^{\gamma t}}{2 \pi} \int_{-\infty}^{+\infty}  
    e^{i t y} (z I - \eta B - M)^{-1} \tilde{f}(z) \,\mathrm{d} y \\
    = \frac{e^{\gamma t}}{2 \pi} \int_{-\infty}^{+\infty} 
    e^{i t y} \big( I - (z I - \eta B)^{-1} M \big)^{-1} 
    (z I - \eta B)^{-1} \tilde{f}(z) \,\mathrm{d} y.
  \end{multline*}

\begin{multline*}
    \|R(T)\| \le \frac{e^{\gamma T}}{2 \pi} \int_{-\infty}^{+\infty}
    \big\| \big( I - (z I - \eta B)^{-1} M \big)^{-1} \big\| \cdot 
    \|(z I - \eta B)^{-1}\| \cdot |\tilde{f}(z)| \,\mathrm{d} y \\ 
    \le \frac{K e^{\gamma T}}{\pi}
    \|f\|_{C^1([0, T])} \int_{-\infty}^{+\infty} 
    \max_{\lambda \in \sigma(B)} |z - \eta \lambda|^{-1}
    \frac{8}{|y| + 4 \gamma} \,\mathrm{d} y \\ 
    \le \frac{8 \sqrt{2} K e^{\gamma T}}{\pi} 
    \|f\|_{C^1([0, T])} 
    \sum_{\lambda \in \sigma(B)} \int_{-\infty}^{+\infty} 
    \frac{1}{|y - \eta \Im(\lambda)| + \gamma - \eta \Re(\lambda)}
    \cdot \frac{1}{|y| + 4 \gamma} \,\mathrm{d} y \\ 
    = \frac{8 \sqrt{2} K e^{\gamma T}}{\pi} 
    \|f\|_{C^1([0, T])} \sum_{\lambda \in \sigma(B)} 
    \mathcal{I}(\eta \Im(\lambda), 0, \gamma - \eta \Re(\lambda), 4 \gamma).
  \end{multline*}

\begin{multline*}
    \|R(T; \theta)\| \le \frac{4 \sqrt{2} \tilde{K} 
    e^{\tilde{\gamma} T}}{\pi}
    \sup_{|\theta| = 1} \|f(\cdot; \theta)\|_{C^1([0, +\infty))} \\
    \sum_{\lambda \in \sigma(\eta B + M(\theta))} 
    \mathcal{I}(\Im(\lambda), 0, \tilde{\gamma} - \Re(\lambda), 
    4 \tilde{\gamma}),
  \end{multline*}

\label{lemma:low_frequency_G}
  If the matrix $B$ is quasi-stable, the following estimate of 
  $G(t, \xi, \eta)$ holds for $\eta > \beta \gamma$:
  \begin{displaymath}
    \|G(t, \xi, \eta)\| \le \frac{C |\xi| e^{\gamma t}}{\eta} 
    \|\exp(H_{11} \cdot)\|_{C^1([0, t])} 
    \log \frac{\eta \delta + \gamma}{\gamma},
  \end{displaymath}
  where $\gamma = \alpha |\xi| + 1$, and the positive constants 
  $C$, $\delta$, $\alpha$ and $\beta$ depend on 
  the matrices $A^j$ and $Q$.
  Furthermore, if the matrix sets $\mathcal{F}_1$ and $\mathcal{F}_2$ defined in 
  \cref{eq:F1,eq:F2}, respectively, are uniformly quasi-stable, then 
  the following estimate of $G(t, \xi, \eta)$ holds for 
  $\eta > \tilde{\beta}(|\xi| + 1)$: 
  \begin{displaymath}
    \|G(t, \xi, \eta)\| \le \frac{\tilde{C} |\xi| e^t}{\eta} 
    \log(\eta \tilde{\delta} + 1),
  \end{displaymath}
  where the positive constants $\tilde{C}$, $\tilde{\delta}$ and 
  $\tilde{\beta}$ depend on the matrices $A^j$ and $Q$.

\label{lemma:low_frequency}
  If \cref{eq} is stiffly well-posed, the following convergence holds 
  for each $t > 0$ and $\Xi > 0$:
  \begin{displaymath}
    \lim \limits_{\eta \to +\infty}
    \norm{ \big( \hat{u}(t, \cdot, \eta) - \exp(H_{11} t) \hat{u}_0
    \big) \mathbbm{1}_{|\cdot| \le \Xi} }_{L^2} = 0.
  \end{displaymath}
  Furthermore, if the matrix sets $\mathcal{F}_1$ and $\mathcal{F}_2$ are uniformly 
  quasi-stable, and the initial data satisfies $U_0 \in H^2$, 
  then there exist positive constants $C$, $\tilde{\delta}$ and 
  $\tilde{\beta}$ dependent on the matrices $A_j$ and $Q$ such that 
  the following estimate holds for each $t > 0$ and 
  $\eta > 2 \tilde{\beta}$:
  \begin{equation}\label{eq:low_frequency_error}
    \norm{ \big( \hat{u}(t, \cdot, \eta) - \exp(H_{11} t) \hat{u}_0
    \big) \mathbbm{1}_{|\cdot| \le \Xi(\eta)} }_{L^2} \le 
    \frac{C e^{t}}{\eta} \|U_0\|_{H^2}
    \log (\eta \tilde{\delta} + 1),
  \end{equation}
  where $\Xi(\eta) = \tilde{\beta}^{-1} \eta - 1$.

\begin{equation}\label{eq:low_frequency_error}
    \norm{ \big( \hat{u}(t, \cdot, \eta) - \exp(H_{11} t) \hat{u}_0
